function useStakeWithdrawState(mode) {
  const initialPosition = useModalLiquidityInitialState();
  const isV2 = initialPosition?.version === ProtocolVersion.V2;
  const gauge = useGaugeStaking(initialPosition);
  const availableRaw = useMemo(() => {
    if (!isV2) return 0n;
    if (mode === "stake") {
      try {
        return BigInt(gauge.unstakedLPBalanceRaw || "0");
      } catch {
        return 0n;
      }
    }
    try {
      return BigInt(gauge.rawStakedBalance || "0");
    } catch {
      return 0n;
    }
  }, [isV2, mode, gauge.unstakedLPBalanceRaw, gauge.rawStakedBalance]);
  return { initialPosition, isV2, gauge, availableRaw };
}
