function formatLP(amountRaw, decimals = 18) {
  if (amountRaw === 0n) return "0.0000";
  const s = amountRaw.toString().padStart(decimals + 1, "0");
  const int = s.slice(0, -decimals);
  const frac = s.slice(-decimals).slice(0, 12);
  return `${Number(int).toLocaleString()}.${frac}`;
}
